"""M5.2D explicit photo selection, private-byte permit and durable single-effect delivery.

Applied predecessors remain byte-for-byte unchanged. Versions 1-5 retain their
closed contracts; v6 requires a distinct finite synthetic admission and READ.
"""

from alembic import op

revision = "0022"
down_revision = "0021"
branch_labels = None
