        "CHECK((content_type='TEXT' AND text IS NOT NULL AND "
        "char_length(text)>0 AND image_file_id IS NULL) OR "
        "(content_type='IMAGE_REFERENCE' AND image_file_id IS NOT NULL) OR "
        "(content_type='PORTFOLIO_PHOTO' AND direction='OUTBOUND' AND text IS "
